(function(){
  'use strict';
  var LOW=[697,770,852,941];
  var HIGH=[1209,1336,1477,1633];
  var KEYS=[
    ['1','2','3','A'],
    ['4','5','6','B'],
    ['7','8','9','C'],
    ['*','0','#','D']
  ];
  function encodeChar(ch){
    ch=String(ch).toUpperCase();
    for(var r=0;r<4;r++) for(var c=0;c<4;c++) if(KEYS[r][c]===ch)
      return {key:ch, low:LOW[r], high:HIGH[c]};
    return null;
  }
  function encode(str){
    if(str==null) return {value:null,error:'输入为空'};
    str=String(str);
    var arr=[];
    for(var i=0;i<str.length;i++){
      var e=encodeChar(str[i]);
      if(!e) return {value:null,error:'非法字符：'+str[i]+'（仅支持 0-9 * # A-D）'};
      arr.push(e);
    }
    return {value:arr, error:''};
  }
  function decode(low,high){
    var r=LOW.indexOf(low), c=HIGH.indexOf(high);
    if(r<0||c<0) return {value:null,error:'频率不在 DTMF 标准集内'};
    return {value:{key:KEYS[r][c], low:low, high:high}, error:''};
  }
  function nearest(set,f){
    var bi=-1, bd=1e9;
    for(var i=0;i<set.length;i++){ var d=Math.abs(set[i]-f); if(d<bd){bd=d;bi=i;} }
    return {idx:bi, dist:bd};
  }
  function detect(lowHz, highHz, tolPct){
    tolPct=(tolPct==null)?1.5:tolPct;
    var ln=nearest(LOW, lowHz), hn=nearest(HIGH, highHz);
    if(ln.idx<0||hn.idx<0) return {value:null,error:'频率超出范围'};
    if(ln.dist > LOW[ln.idx]*tolPct/100) return {value:null,error:'低频 '+lowHz+' Hz 偏离 '+LOW[ln.idx]+' 超出容差'};
    if(hn.dist > HIGH[hn.idx]*tolPct/100) return {value:null,error:'高频 '+highHz+' Hz 偏离 '+HIGH[hn.idx]+' 超出容差'};
    return {value:{key:KEYS[ln.idx][hn.idx], low:LOW[ln.idx], high:HIGH[hn.idx]}, error:''};
  }
  function keypad(){
    var rows=[];
    for(var r=0;r<4;r++){
      var row=[];
      for(var c=0;c<4;c++) row.push({key:KEYS[r][c], low:LOW[r], high:HIGH[c]});
      rows.push(row);
    }
    return {low:LOW, high:HIGH, rows:rows};
  }
  var API={LOW:LOW,HIGH:HIGH,KEYS:KEYS,encode:encode,encodeChar:encodeChar,
           decode:decode,detect:detect,keypad:keypad,nearest:nearest};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__DtmfForge__=API;
})();
